  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const KEY = 'solace-desktop-v1';
  const initial = {
    user:'Alex Morgan', tasks:[false,false,false], notes:[{id:1,title:'A little reminder',body:'Take a moment to make this space yours.\n\nYou can write anything here — thoughts, plans, little things you don’t want to forget.',updated:Date.now()-86400000}], activeNote:1,
    files:[{name:'Getting started',kind:'folder',size:'—'},{name:'Weekend plans',kind:'note',size:'2 KB'},{name:'Moodboard',kind:'image',size:'4.2 MB'},{name:'Read later',kind:'folder',size:'—'},{name:'hello-world.txt',kind:'note',size:'1 KB'},{name:'Sunset study',kind:'image',size:'3.8 MB'}],
    wallpaper:'warm', toggles:{notifications:true,sounds:true,autoSave:true}, visited:Date.now(), sessions:0, trash:0, readMail:[], greeting:'',
  };
  let state;
  try { state = {...initial,...JSON.parse(localStorage.getItem(KEY)||'{}')}; } catch { state = {...initial}; }
  state.tasks ||= [false,false,false]; state.notes ||= [...initial.notes]; state.files ||= [...initial.files]; state.toggles ||= {...initial.toggles}; state.readMail ||= [];
  state.sessions = (state.sessions || 0) + 1; state.lastSeen = Date.now();
  const save = () => { try { localStorage.setItem(KEY, JSON.stringify(state)); } catch {} };
  const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon = name => `<svg class="icon"><use href="#i-${name}"/></svg>`;
  const names = {home:'Desktop',files:'Files',browser:'Browser',mail:'Mail',notes:'Notes',settings:'Settings',activity:'Activity',trash:'Recycle Bin'};
  let z = 25, toastTimer, noteTimer;
  const windows = new Map();
  const layer = $('#window-layer');
  function showToast(message) { const t=$('#toast'); t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100); }
  function timeFmt(date=new Date()) { return date.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'}); }
  function updateClock(){const d=new Date();$('#clock').textContent=timeFmt(d);$('#widget-time').textContent=d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',hour12:false});}
  updateClock();setInterval(updateClock,1000);
  function makeWindow(app){
    let win=document.createElement('section'); win.className=`app-window app-${app}`;win.dataset.app=app;win.style.zIndex=++z;
    const titleIcon={files:'folder',browser:'browser',mail:'mail',notes:'note',settings:'settings',activity:'monitor',trash:'trash',home:'grid'}[app]||'grid';
    win.innerHTML=`<div class="window-titlebar"><div class="window-controls"><button class="window-control close" aria-label="Close"></button><button class="window-control minimize" aria-label="Minimize"></button><button class="window-control maximize" aria-label="Maximize"></button></div><div class="window-title">${icon(titleIcon)}<span>${names[app]||app}</span></div><div class="window-toolbar">${app==='files'?'<button class="new-file">＋ New folder</button>':''}${app==='notes'?'<button class="new-note-toolbar">＋ New note</button>':''}<button class="window-more" title="More">···</button></div></div><div class="window-body"></div>`;
    win.addEventListener('pointerdown',()=>{win.style.zIndex=++z;});
    win.querySelector('.close').onclick=()=>closeApp(app);win.querySelector('.minimize').onclick=()=>win.classList.add('minimized');
    win.querySelector('.maximize').onclick=()=>win.classList.toggle('maximized');win.querySelector('.window-more').onclick=()=>showToast(`${names[app]} · Saved on this computer`);
    makeDraggable(win,win.querySelector('.window-titlebar'));win.querySelector('.window-body').innerHTML=renderApp(app);layer.appendChild(win);windows.set(app,win);
