    makeWindow(app);
  }
  function closeApp(app){const win=windows.get(app);if(win)win.remove();windows.delete(app);$('#active-app').textContent=windows.size?names[[...windows.keys()].at(-1)]:'Desktop';}
  function makeDraggable(win,bar){let sx,sy,ox,oy,moving=false;bar.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;if(win.classList.contains('maximized'))return;moving=true;let r=win.getBoundingClientRect();sx=e.clientX;sy=e.clientY;ox=r.left;oy=r.top;win.style.transform='none';win.style.left=ox+'px';win.style.top=oy-39+'px';bar.setPointerCapture(e.pointerId);});bar.addEventListener('pointermove',e=>{if(!moving)return;win.style.left=Math.max(0,Math.min(innerWidth-win.offsetWidth,ox+e.clientX-sx))+'px';win.style.top=Math.max(0,Math.min(innerHeight-100,oy+e.clientY-sy-39))+'px';});bar.addEventListener('pointerup',()=>moving=false);}
